<div class="publication-list"><?php foreach($publications as$p):$targets=$targetsByPublication[(int)$p['id']]??[];$hasError=(int)$p['failed_count']>0;$scheduled=$p['publish_mode']==='Scheduled';?><article class="publication-row publication-card" data-publication-row data-scheduled="<?= $scheduled?'1':'0'?>" data-error="<?= $hasError?'1':'0'?>"><div class="publication-date"><strong><?= $e(date('d',strtotime($p['scheduled_at']?:$p['created_at'])))?></strong><span><?= $e(strtoupper(date('M',strtotime($p['scheduled_at']?:$p['created_at']))))?></span></div><div class="publication-main"><div class="row-top"><span class="status-pill status-<?= strtolower($e($p['approval_status']))?>"><?= $e($p['approval_status'])?></span><span><?= $e($p['client_name'])?></span><span><?= $e($p['publish_mode']==='Now'?'Immédiate':'Programmée')?></span></div><h3><?= $e($p['master_title'])?></h3><p><?= nl2br($e(mb_strimwidth($p['master_caption'],0,220,'…')))?></p><div class="target-results"><?php foreach($targets as$t):?><div class="target-result state-<?= strtolower($e($t['status']))?>"><span class="network-logo network-<?= $e($t['provider'])?>"><?= strtoupper(substr($t['provider'],0,1))?></span><div><strong><?= $e($providers[$t['provider']]??$t['provider'])?> · <?= $e($t['account_label'])?></strong><small><?= $e($t['remote_deleted_at']?'Supprimée du réseau':$t['status'])?> · tentative <?= (int)$t['attempts']?>/<?= (int)$t['max_attempts']?></small><?php if($t['last_error']):?><em><?= $e($t['last_error'])?></em><?php endif?><?php if($t['external_post_url']&&!$t['remote_deleted_at']):?><a href="<?= $e($t['external_post_url'])?>" target="_blank" rel="noopener">Voir la publication ↗</a><?php endif?></div><div class="target-actions"><?php if($canManage&&$t['status']==='Failed'):?><form method="post"><input type="hidden" name="action" value="retry"><input type="hidden" name="target_id" value="<?= (int)$t['id']?>"><button class="button secondary" type="submit">Relancer</button></form><?php endif?><?php if($canApprove&&$t['status']==='Published'&&$t['provider']==='facebook'&&!$t['remote_deleted_at']):?><form method="post" onsubmit="return confirm('Supprimer réellement cette publication Facebook ?')"><input type="hidden" name="action" value="delete_remote"><input type="hidden" name="target_id" value="<?= (int)$t['id']?>"><button class="button danger-soft" type="submit">Supprimer</button></form><?php endif?></div></div><?php endforeach?></div></div><div class="publication-actions"><?php if($canManage&&$p['approval_status']==='Draft'):?><form method="post"><input type="hidden" name="action" value="submit"><input type="hidden" name="publication_id" value="<?= (int)$p['id']?>"><button class="button secondary" type="submit">Envoyer en validation</button></form><?php endif?><?php if($canApprove&&$p['approval_status']==='Pending'):?><form method="post"><input type="hidden" name="action" value="approve"><input type="hidden" name="publication_id" value="<?= (int)$p['id']?>"><button class="button primary" type="submit">Approuver et exécuter</button></form><?php endif?><?php if($canManage&&in_array($p['approval_status'],['Draft','Pending','Approved'],true)&&(int)$p['published_count']===0):?><form method="post" onsubmit="return confirm('Annuler cette publication ?')"><input type="hidden" name="action" value="cancel"><input type="hidden" name="publication_id" value="<?= (int)$p['id']?>"><button class="button danger-soft" type="submit">Annuler</button></form><?php endif?></div></article><?php endforeach?></div></section></main>
<aside><section class="panel connections-panel"><div class="section-head"><div><span class="publish-kicker">COMPTES META</span><h2>Destinations</h2></div></div><div class="connection-list"><?php foreach($connections as$c):$savedScopes=(array)json_decode((string)($c['scopes_json']??'[]'),true);$permissionReady=!empty($c['last_validated_at'])&&($c['provider']==='facebook'?in_array('pages_manage_posts',$savedScopes,true):(bool)array_intersect(['instagram_content_publish','instagram_business_content_publish'],$savedScopes));?><article><span class="network-logo network-<?= $e($c['provider'])?>"><?= strtoupper(substr($c['provider'],0,1))?></span><div><strong><?= $e($c['account_label'])?></strong><small><?= $e($providers[$c['provider']]??$c['provider'])?> · <?= $e($c['client_name'])?></small><?php if($canManage&&in_array($c['provider'],['facebook','instagram'],true)&&($c['status']!=='Connected'||!$permissionReady)):?><a class="oauth-link" href="<?= $e(route_url('/social-oauth/connect/'.(int)$c['id'])) ?>" target="_blank" rel="noopener noreferrer"><?= $c['status']==='Connected'?'Mettre à jour les droits':'Connecter avec Meta' ?> ↗</a><?php endif?></div><span class="connection-state state-<?= strtolower($e($c['status']))?>"><?= $c['status']==='Connected'?($permissionReady?'Prêt':'Droits incomplets'):($c['status']==='Pending'?'OAuth requis':$e($c['status']))?></span></article><?php endforeach?></div>
<?php if($canManage):?><details class="connect-form"><summary>+ Connecter Meta à un client</summary><form method="post"><input type="hidden" name="action" value="connection"><input type="hidden" name="provider" value="facebook"><label>Entreprise<select name="client_id" required><option value="">Sélectionner</option><?php foreach($clients as$c):?><option value="<?= (int)$c['id']?>"><?= $e($c['name'])?></option><?php endforeach?></select></label><label>Libellé interne<input name="account_label" required placeholder="Connexion Meta"></label><button class="button primary" type="submit">Préparer la connexion</button><small>Facebook et les comptes Instagram liés seront importés pendant OAuth.</small></form></details><?php endif?></section></aside></div>
<dialog class="compose-dialog" id="composeDialog"><form method="post" enctype="multipart/form-data" class="compose-form"><input type="hidden" name="action" value="publication"><header><div><span class="publish-kicker">NOUVELLE PUBLICATION</span><h2>Composer pour Meta</h2></div><button type="button" class="dialog-close" data-close-compose aria-label="Fermer">×</button></header><div class="compose-grid"><section><label>Entreprise<select name="client_id" id="publishClient" required><option value="">Choisir l’entreprise</option><?php foreach($clients as$c):?><option value="<?= (int)$c['id']?>"><?= $e($c['name'])?></option><?php endforeach?></select></label><label>Titre interne<input name="master_title" required placeholder="Campagne lancement produit"></label><div class="caption-editor"><label>Contenu maître</label><div class="text-toolbar" role="toolbar" aria-label="Mise en forme du texte"><button type="button" data-text-style="bold"><b>B</b></button><button type="button" data-text-style="italic"><i>I</i></button><button type="button" data-text-style="boldItalic"><b><i>BI</i></b></button><button type="button" data-text-style="mono">M</button><span data-char-count>0 caractères</span></div><textarea name="master_caption" id="masterCaption" required rows="7" placeholder="Écrivez le message source…"></textarea><div class="hashtag-row"><input type="text" data-hashtags placeholder="marketing digital, conseil, produit"><button class="button secondary" type="button" data-add-hashtags>Ajouter les hashtags</button></div><div class="caption-preview"><span>Aperçu publication</span><p data-caption-preview>Votre aperçu apparaîtra ici…</p></div></div><label>Importer une image <small>JPEG/PNG, 20 Mo max. JPEG obligatoire pour Instagram.</small><input type="file" name="media_file" accept="image/jpeg,image/png"></label><label>ou URL publique HTTPS du média<input name="media_url" placeholder="https://…"></label><div class="schedule-row"><label>Diffusion<select name="publish_mode" id="publishMode"><option value="Scheduled">Programmer</option><option value="Now">Publier dès approbation</option></select></label><label id="scheduleField">Date et heure<input type="datetime-local" name="scheduled_at"></label></div></section><section class="targets-editor"><h3>Destinations et adaptations</h3><p>Sélectionnez les pages du client, puis ajustez le texte.</p><?php foreach($readyConnections as$c):?><label class="target-card" data-client="<?= (int)$c['client_id']?>"><span><input type="checkbox" name="connection_ids[]" value="<?= (int)$c['id']?>"><b><?= $e($providers[$c['provider']]??$c['provider'])?></b> · <?= $e($c['account_label'])?></span><textarea name="variant[<?= $e($c['provider'])?>]" rows="3" placeholder="Laisser vide pour reprendre le contenu maître"></textarea></label><?php endforeach?></section></div><footer><button class="button secondary" type="submit">Enregistrer en brouillon</button><button class="button primary" type="submit" name="submit_approval" value="1">Envoyer en validation</button></footer></form></dialog>
<script src="<?= $e(app_url('/public/assets/social-composer.js?v=1')) ?>"></script><script>(function(){const d=document.getElementById('composeDialog');document.querySelector('[data-open-compose]')?.addEventListener('click',()=>d.showModal());document.querySelector('[data-close-compose]')?.addEventListener('click',()=>d.close());d?.addEventListener('click',e=>{if(e.target===d)d.close()});const client=document.getElementById('publishClient');client?.addEventListener('change',()=>document.querySelectorAll('.target-card').forEach(x=>x.hidden=client.value!==''&&x.dataset.client!==client.value));const mode=document.getElementById('publishMode'),field=document.getElementById('scheduleField'),date=field?.querySelector('input');function sync(){const now=mode?.value==='Now';if(field)field.hidden=now;if(date)date.required=!now}mode?.addEventListener('change',sync);sync();document.querySelectorAll('[data-publication-filters] button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-publication-filters] button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-publication-row]').forEach(row=>row.hidden=b.dataset.filter==='scheduled'?row.dataset.scheduled!=='1':b.dataset.filter==='errors'?row.dataset.error!=='1':false)}));})();</script>